// src/shared.ts
var CHANNEL = "kazzware.v1";
function object(value) {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("Expected an object.");
  return value;
}
function uniqueRange(source, selected) {
  if (!selected)
    return;
  const start = source.indexOf(selected);
  if (start < 0 || source.indexOf(selected, start + 1) >= 0)
    return;
  return { start, end: start + selected.length };
}
function textareaRange(source, start, end) {
  const offset = (position) => {
    let displayed = 0, original = 0;
    while (original < source.length && displayed < position) {
      if (source[original] === "\r" && source[original + 1] === `
`)
        original++;
      original++;
      displayed++;
    }
    return original;
  };
  return { start: offset(start), end: offset(end) };
}
function textareaOffset(source, offset) {
  return source.slice(0, offset).replace(/\r\n?/g, `
`).length;
}
function slopHits(text, phrases, wholeWords) {
  return phrases.map((phrase) => {
    const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const pattern = wholeWords ? `(?<![\\p{L}\\p{N}_])${escaped}(?![\\p{L}\\p{N}_])` : escaped;
    return { phrase, count: Array.from(text.matchAll(new RegExp(pattern, "giu"))).length };
  }).filter((x) => x.count > 0);
}
function escapeHTML(text) {
  return text.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

// src/gallery.ts
function galleryHTML(page) {
  const posts = page.posts.map((post) => `<article><div class="byline">${escapeHTML(post.author)}</div><h2>${escapeHTML(post.title)}</h2><p>${escapeHTML(post.body)}</p><div class="actions"><button data-vote="${escapeHTML(post.id)}" aria-pressed="${page.votes.includes(post.id)}">${page.votes.includes(post.id) ? "♥ Liked" : "♡ Like"}</button><button data-reply="${escapeHTML(post.id)}">Reply</button></div>${page.comments.filter((c) => c.postId === post.id).map((c) => `<div class="comment"><b>${escapeHTML(c.author)}</b><p>${escapeHTML(c.body)}</p></div>`).join("")}<form data-comment="${escapeHTML(post.id)}" hidden><label>Your comment<textarea maxlength="2000" required></textarea></label><button type="submit">Post comment</button></form></article>`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(page.title)}</title><style>
*{box-sizing:border-box}body{margin:0;padding:18px 14px 40px;background:#11131c;color:#edf0fa;font:14px/1.65 system-ui,sans-serif;overflow-wrap:anywhere}header{border-bottom:1px solid #34394e;padding-bottom:18px;margin-bottom:20px}.brand{font-size:10px;letter-spacing:2px;color:#a5d7e9;text-transform:uppercase}h1{font-size:23px;line-height:1.2;letter-spacing:-.5px}h2{font-size:17px;line-height:1.35;margin:8px 0}p{white-space:pre-wrap;margin:9px 0}.subtitle,.byline{color:#aab0c5;font-size:12px}.byline{color:#ff7f94}article{padding:17px 14px;background:#1a1d29;border:1px solid #2a3042;border-radius:14px;margin:14px 0}.actions{display:flex;gap:8px;margin-top:17px}button{cursor:pointer;color:#d8e8f4;background:#262c3d;border:1px solid #3b455a;border-radius:16px;padding:9px 15px;font:inherit;min-height:40px}button[aria-pressed=true]{color:#ff9aaa;border-color:#aa5268}.comment{border-left:2px solid #657c9a;padding:5px 12px;margin:16px 0 0}.comment b{font-size:12px;color:#b7deeb}textarea{display:block;width:100%;min-height:80px;margin:6px 0 10px;background:#0e111b;color:#fff;border:1px solid #52627c;border-radius:8px;padding:10px;font:inherit}form{margin-top:15px}button:focus-visible,textarea:focus-visible{outline:2px solid #b7ebff;outline-offset:3px}.wiki{background:#efece4;color:#252f3a}.wiki article{background:transparent;border:0;border-radius:0;border-bottom:1px solid #c7c5bf;padding:12px 0}.wiki h1,.wiki h2{font-family:Georgia,serif}.wiki .byline,.wiki .subtitle{color:#5d6269}.wiki .brand{color:#354e66}.thread article{border-radius:0;border-width:0 0 1px;background:transparent;margin:0;padding:20px 4px}.forum .brand{color:#ff987b}
</style></head><body class="${page.format}"><header><span class="brand">Peanut Gallery / ${page.format === "forum" ? "r/plotjudgement" : page.format === "thread" ? "fandom feed" : "the unofficial wiki"}</span><h1>${escapeHTML(page.title)}</h1><p class="subtitle">Fictional fandom · ${new Date(page.createdAt).toISOString().slice(0, 10)} · Kept outside your roleplay</p></header>${posts}<script>
document.addEventListener('click',function(event){var target=event.target.closest('button');if(!target)return;if(target.dataset.vote){window.spindleSandbox.postMessage({kind:'vote',postId:target.dataset.vote});target.disabled=true;}if(target.dataset.reply){var form=target.closest('article').querySelector('form');form.hidden=!form.hidden;if(!form.hidden)form.querySelector('textarea').focus();}});
document.addEventListener('submit',function(event){var form=event.target;if(!form.dataset.comment)return;event.preventDefault();var input=form.querySelector('textarea');if(!input.value.trim())return;window.spindleSandbox.postMessage({kind:'comment',postId:form.dataset.comment,text:input.value});form.querySelector('button').disabled=true;});
</script></body></html>`;
}

