// src/frontend.ts
var TABS = [["home", "Kazz"], ["edit", "Editor"], ["slop", "De-slop"], ["chat", "Chat"], ["gallery", "Gallery"], ["notebook", "Notebook"], ["settings", "Settings"]];
function randomId() {
  return Array.from(crypto.getRandomValues(new Uint8Array(16)), (byte) => byte.toString(16).padStart(2, "0")).join("");
}
function setup(ctx) {
  const stateAPI = ctx.state;
  if (!stateAPI)
    throw new Error("KazzWare requires the Lumiverse 1.2.5 frontend state API. Update Lumiverse and reload.");
  ctx.deferReady();
  const disposers = [];
  const client = randomId();
  let binding = randomId();
  let chatId = null;
  let destroyed = false;
  let opened = false;
  let tab = "home";
  let view;
  let target;
  let range;
  let selectedText = "";
  let selectedMessageId = null;
  let selectionRequest = 0;
  let direction = "";
  let askDraft = "";
  let slopDraft;
  let settingsDraft;
  let pageId = "";
  let frame;
  let status = "Open a chat to wake Kazz.";
  let error = false;
  let busy = 0;
  const pending = new Map;
  const mascot = ctx.ui.createFloatWidget({ width: 110, height: 110, initialPosition: { x: Math.max(0, window.innerWidth - 125), y: Math.max(0, window.innerHeight - 245) }, snapToEdge: true, chromeless: true, tooltip: "KazzWare · your in-chat accomplice" });
  const panel = ctx.ui.createFloatWidget({ width: Math.min(410, window.innerWidth - 16), height: Math.min(720, window.innerHeight - 24), initialPosition: { x: Math.max(8, window.innerWidth - 435), y: 12 }, chromeless: true, tooltip: "KazzWare" });
  for (const widget of [mascot, panel]) {
    widget.root.style.width = "100%";
    widget.root.style.height = "100%";
  }
  panel.root.style.userSelect = "text";
  panel.root.style.touchAction = "pan-y";
  const petRoot = mascot.root.attachShadow({ mode: "open" });
  petRoot.innerHTML = `<style>${CSS}</style><button class="mascot" aria-label="Open KazzWare"><img alt="Kazz, a silver-haired cyber-scorpion companion"><span class="dot"></span></button>`;
  const petButton = petRoot.querySelector("button");
  const petImage = petRoot.querySelector("img");
  const root = panel.root.attachShadow({ mode: "open" });
  root.innerHTML = `<style>${CSS}</style><section class="shell" aria-label="KazzWare"><header class="top"><div class="title"><span class="brand">KAZZWARE</span><span class="badge">CHAT COMPANION</span><div class="chat-name"></div></div><button class="icon close" aria-label="Close KazzWare">✕</button></header><nav aria-label="KazzWare sections"></nav><main class="body"></main><footer class="status" role="status" aria-live="polite"><span></span><button class="cancel" hidden>Stop</button></footer></section>`;
  const body = root.querySelector(".body");
  const nav = root.querySelector("nav");
  const statusBox = root.querySelector(".status");
  body.addEventListener("pointerdown", (event) => event.stopPropagation());
  nav.addEventListener("pointerdown", (event) => event.stopPropagation());
  const notify = (text, failed = false) => {
    status = text;
    error = failed;
    paintStatus();
  };
  function paintStatus() {
    statusBox.querySelector("span").textContent = status;
    statusBox.classList.toggle("error", error);
    statusBox.querySelector("button").hidden = busy === 0;
    petButton.classList.toggle("busy", busy > 0);
    petImage.src = busy ? kazz_working_default : opened ? kazz_active_default : kazz_idle_default;
    body.querySelectorAll("[data-mutate]").forEach((button) => {
      button.disabled = busy > 0;
    });
  }
  function rpc(action, data = {}) {
    if (destroyed)
      return Promise.reject(new Error("KazzWare closed."));
    const id = randomId();
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        pending.delete(id);
        reject(new Error("Kazz did not receive a response. Reload to check completed changes."));
      }, 610000);
      pending.set(id, { resolve: (result) => resolve(result), reject, timer });
      ctx.sendToBackend({ channel: CHANNEL, client, binding, chatId, id, action, data });
    });
  }
  disposers.push(ctx.onBackendMessage((payload) => {
    let reply;
    try {
      reply = object(payload);
    } catch {
      return;
    }
    if (reply.channel !== CHANNEL || reply.client !== client || reply.binding !== binding || destroyed)
      return;
    const request = pending.get(reply.id);
    if (!request)
      return;
    if (reply.progress) {
      notify(reply.progress);
      return;
    }
    clearTimeout(request.timer);
    pending.delete(reply.id);
    reply.ok ? request.resolve(reply.result) : request.reject(new Error(reply.error || "KazzWare request failed."));
  }));
  async function run(action, data = {}, success = "Done. Your changes are saved.") {
    const origin = binding;
    busy++;
    paintStatus();
    notify("Working…");
    try {
      const result = await rpc(action, data);
      if (origin !== binding || destroyed)
        return;
      if (result) {
        view = result;
        await refreshTarget();
        if (origin !== binding)
          return;
        render();
      }
      notify(success);
    } catch (err) {
      if (origin === binding && !destroyed) {
        notify(err instanceof Error ? err.message : "Something went wrong.", true);
        try {
          const refreshed = await rpc("load");
          if (origin === binding) {
            view = refreshed;
            await refreshTarget();
            if (origin === binding)
              render();
          }
        } catch {}
      }
    } finally {
      if (origin === binding) {
        busy = Math.max(0, busy - 1);
        paintStatus();
      }
    }
  }
  async function refreshTarget() {
    if (!target)
      return;
    const origin = binding, id = target.id;
    try {
      const current = await rpc("message", { messageId: id });
      if (origin === binding && target?.id === id && (current.content !== target.content || current.swipe_id !== target.swipe_id)) {
        target = current;
        range = undefined;
      }
    } catch {
      if (origin === binding && target?.id === id) {
        target = undefined;
        range = undefined;
      }
    }
  }
  function show(next = tab) {
    opened = true;
    tab = next;
    panel.setVisible(!!chatId);
    render();
  }
  function hide() {
    opened = false;
    panel.setVisible(false);
    petButton.focus();
    paintStatus();
  }
  petButton.addEventListener("click", () => opened ? hide() : show());
  root.querySelector(".close").addEventListener("click", hide);
  root.querySelector(".cancel").addEventListener("click", () => {
    rpc("cancel").catch(() => {});
    notify("Stopping…");
  });
  nav.innerHTML = TABS.map(([key, label]) => `<button data-tab="${key}">${label}</button>`).join("");
  nav.addEventListener("click", (ev) => {
    const button = ev.target.closest("button");
    if (button)
      show(button.dataset.tab);
  });
  root.addEventListener("keydown", (ev) => {
    if (ev.key === "Escape")
      hide();
  });
  const inputAction = ctx.ui.registerInputBarAction({ id: "kazzware-open", label: "KazzWare", subtitle: "Your in-chat accomplice", iconUrl: kazz_idle_default });
  disposers.push(inputAction.onClick(() => show()));
  disposers.push(() => inputAction.destroy());
  if (ctx.registerMessageAction) {
    const action = ctx.registerMessageAction({ id: "kazzware-edit", label: "Send to Kazz", onClick: (id) => {
      selectMessage(id, selectedMessageId === id ? selectedText : "");
    } });
    disposers.push(() => action.destroy());
  }
  async function selectMessage(id, highlighted = "") {
    const origin = binding, sequence = ++selectionRequest;
    try {
      const message = await rpc("message", { messageId: id });
      if (origin !== binding || sequence !== selectionRequest)
        return;
      target = message;
      range = highlighted ? uniqueRange(message.content, highlighted) : undefined;
      show("edit");
      notify(highlighted && !range ? "That highlight cannot be mapped exactly. Select it in the source box below." : range ? "Only the highlighted source text will change." : "Message selected. Edits apply immediately; Undo stays available.");
    } catch (err) {
      if (origin === binding)
        notify(err.message, true);
    }
  }
  const captureSelection = () => {
    const selection = window.getSelection();
    if (!selection?.rangeCount || selection.isCollapsed)
      return;
    const anchor = selection.anchorNode?.nodeType === Node.ELEMENT_NODE ? selection.anchorNode : selection.anchorNode?.parentElement;
    const focus = selection.focusNode?.nodeType === Node.ELEMENT_NODE ? selection.focusNode : selection.focusNode?.parentElement;
    if (!anchor || !focus || root.contains(anchor) || petRoot.contains(anchor))
      return;
    const a = ctx.dom.getMessageId(anchor), b = ctx.dom.getMessageId(focus);
    if (a && a === b) {
      selectedText = selection.toString();
      selectedMessageId = a;
    }
  };
  document.addEventListener("selectionchange", captureSelection);
  disposers.push(() => document.removeEventListener("selectionchange", captureSelection));
  const resize = () => {
    const mobile = window.innerWidth <= 600;
    panel.setFullscreen(mobile);
    panel.root.style.height = mobile ? `${Math.max(200, window.visualViewport?.height || window.innerHeight)}px` : "100%";
    if (mobile)
      return;
    panel.setSize(Math.min(410, window.innerWidth - 16), Math.max(200, Math.min(720, (window.visualViewport?.height || window.innerHeight) - 24)));
    const pos = panel.getPosition();
    panel.moveTo(Math.max(8, Math.min(pos.x, window.innerWidth - Math.min(410, window.innerWidth - 16) - 8)), Math.max(8, Math.min(pos.y, 24)));
  };
  window.addEventListener("resize", resize);
  window.visualViewport?.addEventListener("resize", resize);
  disposers.push(() => {
    window.removeEventListener("resize", resize);
    window.visualViewport?.removeEventListener("resize", resize);
  });
  const heartbeat = setInterval(() => {
    if (chatId)
      rpc("heartbeat").catch(() => {});
  }, 45000);
  disposers.push(() => clearInterval(heartbeat));
  function changeChat(value) {
    const next = value && typeof value === "object" && "chatId" in value ? value.chatId : null;
    if (next === chatId && view)
      return;
    for (const item of pending.values()) {
      clearTimeout(item.timer);
      item.reject(new Error("Chat changed."));
    }
    pending.clear();
    binding = randomId();
    chatId = next;
    view = undefined;
    target = undefined;
    range = undefined;
    direction = "";
    askDraft = "";
    slopDraft = undefined;
    settingsDraft = undefined;
    selectedText = "";
    selectedMessageId = null;
    pageId = "";
    busy = 0;
    frame?.destroy();
    frame = undefined;
    mascot.setVisible(!!chatId);
    panel.setVisible(!!chatId && opened);
    inputAction.setEnabled(!!chatId);
    render();
    if (chatId)
      run("bind", {}, "Kazz is here. Pick a message or ask a favor.");
    else {
      rpc("bind").catch(() => {});
      notify("Open a chat to wake Kazz.");
    }
  }
  disposers.push(stateAPI.subscribe("chat.active", changeChat));
  disposers.push(ctx.events.on("GENERATION_ENDED", (payload) => {
    const event = payload;
    if (event.chatId === chatId && view?.state.settings.galleryEnabled && event.messageId && event.generationType === "normal" && !event.error)
      run("tick", { messageId: event.messageId, generationType: event.generationType }, "Peanut Gallery is up to date.");
  }));
  function button(selector, handler) {
    body.querySelector(selector)?.addEventListener("click", handler);
  }
  function render() {
    frame?.destroy();
    frame = undefined;
    root.querySelector(".chat-name").textContent = view?.chatName || "Current chat";
    nav.querySelectorAll("button").forEach((b) => {
      b.classList.toggle("active", b.dataset.tab === tab);
      b.setAttribute("aria-current", b.dataset.tab === tab ? "page" : "false");
    });
    if (!view) {
      body.innerHTML = '<p class="empty">Connecting to this chat…</p>';
      paintStatus();
      return;
    }
    mascot.setSize(view.state.settings.mascotSize, view.state.settings.mascotSize);
    if (tab === "home") {
      body.innerHTML = `<div class="hero"><div><div class="eyebrow">Local menace. Useful accomplice.</div><h2>Your plot.<br>My problem.</h2><p>Hand me the awkward prose. I’ll handle the damn prose.</p></div><img src="${kazz_active_default}" alt="Kazz looking attentive"></div><div class="stack"><button class="tile" data-go="edit"><strong>Put that message on the table</strong><span>Reform it, cut the slop, or change only a selection.</span></button><button class="tile" data-go="chat"><strong>Ask your accomplice</strong><span>Find a line. Untangle continuity. Build some lore.</span></button><button class="tile" data-go="gallery"><strong>The fandom has entered the chat</strong><span>A separate little internet with far too many opinions.</span></button></div><div class="note">Edits land immediately. Open Editor for the Undo history.</div>${view.state.settings.connectionId ? "" : '<button class="primary" data-go="settings">Choose Kazz’s connection</button>'}`;
      body.querySelectorAll("[data-go]").forEach((b) => b.addEventListener("click", () => show(b.dataset.go)));
    }
    if (tab === "edit")
      renderEditor();
    if (tab === "slop")
      renderSlop();
    if (tab === "chat")
      renderChat();
    if (tab === "gallery")
      renderGallery();
    if (tab === "notebook")
      renderNotebook();
    if (tab === "settings")
      renderSettings();
    paintStatus();
  }
  function renderEditor() {
    const messages = view.messages;
    body.innerHTML = `<h2>Message surgery</h2><p class="muted">Pick a message, or use “Send to Kazz” in its menu.</p><label class="field">Recent messages<select class="messages"><option value="">Choose a message…</option>${[...messages].reverse().map((m) => `<option value="${escapeHTML(m.id)}" ${m.id === target?.id ? "selected" : ""}>${m.index_in_chat + 1} · ${escapeHTML(m.name)} · ${escapeHTML(m.content.slice(0, 65).replace(/\n/g, " "))}</option>`).join("")}</select></label>${view.totalMessages > messages.length ? "<small>Showing the latest 100. Use the message menu or ask Kazz to search older messages.</small>" : ""}${target ? `<label class="field">Source text · select a section to limit the edit<textarea class="raw" readonly aria-label="Message source">${escapeHTML(target.content)}</textarea><div class="range"></div></label><div class="row"><button class="clear-range">Use whole message</button><button class="reload">Reload source</button></div><label class="field">Your direction<textarea class="direction" placeholder="Shorten this. Keep the tension, lose the three-paragraph weather report.">${escapeHTML(direction)}</textarea></label><div class="row"><button class="primary apply" data-mutate>Edit now</button><button class="deslop" data-mutate>De-slop now</button></div><small>Same narrative moment unless you explicitly ask to advance it.</small>` : '<div class="empty">No message selected yet.</div>'}<h3 style="margin-top:26px">Undo history · latest 20 edits</h3>${[...view.state.undo].reverse().map((u) => `<div class="history"><strong>${escapeHTML(u.label)}</strong><p>${new Date(u.createdAt).toLocaleString()} · ${u.status === "prepared" ? "Recovery record — check current message" : u.status}</p><button data-undo="${escapeHTML(u.id)}" data-mutate ${u.status === "undone" ? "hidden" : ""}>Undo this edit</button></div>`).join("") || '<p class="empty">No Kazz edits in this chat yet.</p>'}`;
    body.querySelector("select").addEventListener("change", (ev) => {
      const id = ev.target.value;
      if (id)
        selectMessage(id);
    });
    const raw = body.querySelector(".raw");
    const selectionLabel = () => {
      const label = body.querySelector(".range");
      if (label)
        label.textContent = range ? `Selection only · ${range.end - range.start} characters` : "Whole message selected";
    };
    if (raw) {
      if (range)
        raw.setSelectionRange(textareaOffset(target.content, range.start), textareaOffset(target.content, range.end));
      raw.addEventListener("select", () => {
        range = raw.selectionEnd > raw.selectionStart ? textareaRange(target.content, raw.selectionStart, raw.selectionEnd) : undefined;
        selectionLabel();
      });
      body.querySelector(".direction").addEventListener("input", (ev) => {
        direction = ev.target.value;
      });
      button(".clear-range", () => {
        range = undefined;
        raw.setSelectionRange(0, 0);
        selectionLabel();
      });
      button(".reload", () => {
        if (target)
          selectMessage(target.id);
      });
      const edit = (mode) => {
        if (target)
          run("edit", { messageId: target.id, expected: target.content, swipe: target.swipe_id, direction, mode, range }, mode === "deslop" && !slopHits(range ? target.content.slice(range.start, range.end) : target.content, view.state.settings.slop, view.state.settings.wholeWords).length ? "No banned phrases found." : "Edit completed. Undo is below if wording changed.");
      };
      button(".apply", () => edit("reform"));
      button(".deslop", () => edit("deslop"));
      selectionLabel();
    }
    body.querySelectorAll("[data-undo]").forEach((b) => b.addEventListener("click", () => {
      run("undo", { undoId: b.dataset.undo }, "Undone. Previous wording restored.");
    }));
  }
  function renderSlop() {
    body.innerHTML = `<h2>Eviction list</h2><p class="muted">One phrase or word per line. Literal matching; case-insensitive.</p><label class="field">Banned phrases<textarea class="phrases" style="min-height:240px" maxlength="60300">${escapeHTML(slopDraft ?? view.state.settings.slop.join(`
`))}</textarea></label><label class="check"><input class="whole" type="checkbox" ${view.state.settings.wholeWords ? "checked" : ""}>Match whole words / phrase boundaries</label><div class="row"><button class="primary save-slop" data-mutate>Save list</button><button class="scan">Scan selected message</button></div><div class="hits field"></div><div class="note">De-slop rewrites coherently, then scans the result again. If banned wording remains, the original stays intact.</div>`;
    body.querySelector(".phrases").addEventListener("input", (ev) => {
      slopDraft = ev.target.value;
    });
    const phrases = () => body.querySelector(".phrases").value.split(/\r?\n/).map((p) => p.trim()).filter(Boolean);
    button(".save-slop", () => {
      const next = { ...view.state.settings, slop: phrases(), wholeWords: body.querySelector(".whole").checked };
      slopDraft = undefined;
      run("settings", { settings: next }, "Eviction list saved for this chat.");
    });
    button(".scan", () => {
      const hits = target ? slopHits(target.content, phrases(), body.querySelector(".whole").checked) : [];
      body.querySelector(".hits").textContent = !target ? "Select a message in Editor first." : hits.length ? hits.map((h) => `${h.phrase} × ${h.count}`).join(`
`) : "Clean. No matches in the selected source.";
    });
  }
  function renderChat() {
    body.innerHTML = `<h2>You & Kazz</h2><p class="muted">Private to this chat. Ask for a favor; I’ll do the legwork.</p><div class="transcript">${view.state.turns.map((t) => `<div class="bubble ${t.role}"><span class="speaker">${t.role === "user" ? "YOU" : "KAZZ"}</span>${escapeHTML(t.content)}</div>`).join("") || '<div class="note">“Find the first time they mentioned the lighthouse.”<br>“Make message 12 less repetitive.”<br>“Build a lorebook from this chat.”</div>'}</div><label>Your message<textarea class="ask" placeholder="Alright, Kazz…">${escapeHTML(askDraft)}</textarea></label><button class="primary send" data-mutate style="margin-top:10px">Send to Kazz</button><small style="display:block;margin-top:10px">Requested message edits happen immediately. Other reference libraries are read-only.</small>`;
    body.querySelector(".ask").addEventListener("input", (ev) => {
      askDraft = ev.target.value;
    });
    button(".send", () => {
      const text = askDraft;
      if (!text.trim())
        return;
      askDraft = "";
      run("ask", { text }, "Kazz has replied.");
    });
  }
  function renderGallery() {
    const state = view.state;
    const page = state.pages.find((p) => p.id === pageId) || state.pages.at(-1);
    pageId = page?.id || "";
    body.innerHTML = `<h2>Peanut Gallery <span class="badge">FICTIONAL</span></h2><label class="check"><input class="enabled" type="checkbox" ${state.settings.galleryEnabled ? "checked" : ""}>Let the fandom comment</label><small>Every ${state.settings.interval} normal replies · ${state.count} / ${state.settings.interval} counted. No regeneration, swipe or Kazz-reply triggers.</small><div class="row field"><button class="primary generate" data-mutate ${state.settings.galleryEnabled ? "" : "hidden"}>Fresh drama</button><button class="gallery-settings">Configure</button></div><label>Saved pages<select class="pages"><option value="">${state.pages.length ? "Choose a page…" : "No pages yet"}</option>${[...state.pages].reverse().map((p) => `<option value="${escapeHTML(p.id)}" ${p.id === pageId ? "selected" : ""}>${escapeHTML(p.title)}</option>`).join("")}</select></label>${page ? '<div class="phone"><div class="island"></div><div class="screen"></div><div class="phone-bottom"></div></div>' : '<div class="note">Your fandom lives here. Enable it and tap Fresh drama, or let normal roleplay replies bring the next edition.</div>'}`;
    body.querySelector(".enabled").addEventListener("change", (ev) => {
      const galleryEnabled = ev.target.checked;
      run("settings", { settings: { ...state.settings, galleryEnabled } }, galleryEnabled ? "The fandom is awake." : "Peanut Gallery paused. Saved pages remain.");
    });
    button(".generate", () => {
      pageId = "";
      run("gallery", {}, "Fresh drama has arrived.");
    });
    button(".gallery-settings", () => show("settings"));
    body.querySelector(".pages").addEventListener("change", (ev) => {
      pageId = ev.target.value;
      render();
    });
    if (page) {
      const framePageId = page.id, origin = binding, screen = body.querySelector(".screen");
      rpc("page", { pageId: framePageId }).then((fullPage) => {
        if (!fullPage || origin !== binding || tab !== "gallery" || !root.contains(screen))
          return;
        frame = ctx.dom.createSandboxFrame({ html: galleryHTML(fullPage), autoResize: false, minHeight: 350, initialHeight: 440, maxHeight: 440 });
        frame.element.title = "Fictional Peanut Gallery page";
        screen.append(frame.element);
        frame.onMessage((payload) => {
          let data;
          try {
            data = object(payload);
          } catch {
            return;
          }
          if (!["vote", "comment"].includes(String(data.kind)) || typeof data.postId !== "string" || !fullPage.posts.some((p) => p.id === data.postId))
            return;
          run("react", { pageId: framePageId, kind: data.kind, postId: data.postId, text: data.text }, "Saved in your fictional fandom.");
        });
      }).catch((err) => {
        if (origin === binding)
          notify(err.message, true);
      });
    }
  }
  function renderNotebook() {
    body.innerHTML = `<h2>Continuity notebook</h2><p class="muted">Summaries cover the entire current chat. Lorebooks are created in Lumiverse and attached to this chat.</p><div class="row field"><button class="primary summarize" data-mutate>Summarize chat</button><button class="lorebook" data-mutate>Create lorebook</button></div><small>Long chats require several model calls. Stop cancels unfinished work.</small>${[...view.state.summaries].reverse().map((s) => `<details class="history"><summary>${s.messages} messages · ${new Date(s.createdAt).toLocaleString()}</summary><div class="summary">${escapeHTML(s.text)}</div></details>`).join("") || '<div class="empty">No summaries yet.</div>'}<h3 style="margin-top:20px">Created lorebooks</h3>${view.state.lorebooks.map((b) => `<div class="history"><strong>${escapeHTML(b.name)}</strong><p>ID: ${escapeHTML(b.id)}</p><small>Manage entries and attachment in Lumiverse’s lorebook editor. Interrupted creations may be incomplete.</small></div>`).join("") || '<p class="empty">No lorebooks created by Kazz yet.</p>'}`;
    button(".summarize", () => {
      run("summary", {}, "Full-chat summary saved in the notebook.");
    });
    button(".lorebook", () => {
      run("lorebook", {}, "Lorebook created and attached to this chat.");
    });
    const summaries = [...view.state.summaries].reverse();
    body.querySelectorAll("details").forEach((details, index) => {
      details.addEventListener("toggle", () => {
        if (!details.open)
          return;
        const origin = binding;
        rpc("summaryContent", { summaryId: summaries[index].id }).then((text) => {
          if (origin === binding && root.contains(details))
            details.querySelector(".summary").textContent = text;
        }).catch((err) => {
          if (origin === binding)
            notify(err.message, true);
        });
      });
    });
  }
  function renderSettings() {
    const s = settingsDraft || view.state.settings;
    body.innerHTML = `<h2>Accomplice settings</h2><p class="muted">Saved separately for each chat.</p><label class="field">Kazz’s connection<select class="connection"><option value="">Choose a connection…</option>${view.connections.map((c) => `<option value="${escapeHTML(c.id)}" ${c.id === s.connectionId ? "selected" : ""}>${escapeHTML(c.name)} · ${escapeHTML(c.model)}</option>`).join("")}</select></label><small>Uses this saved connection for every Kazz request. Your roleplay connection stays as it is.</small><label class="field">Recent messages in working context (5–100)<input class="context" type="number" min="5" max="100" value="${s.contextMessages}"></label><label class="field">Gallery interval (normal replies)<input class="interval" type="number" min="1" max="100" value="${s.interval}"></label><label class="field">Gallery format<select class="format">${[["random", "Surprise me"], ["forum", "AITA / discussion forum"], ["thread", "Fandom social thread"], ["wiki", "Unofficial wiki"]].map(([key, label]) => `<option value="${key}" ${key === s.format ? "selected" : ""}>${label}</option>`).join("")}</select></label><label class="field">Mascot size<input class="size" type="range" min="70" max="180" value="${s.mascotSize}"></label><div class="row"><button class="primary save-settings" data-mutate>Save settings</button><button class="reload-state">Reload</button></div><div class="note">Context goes to the connection you select. Search can inspect older messages; summaries read the whole chat. Kazz never receives connection API keys.</div>`;
    const read = () => ({ ...view.state.settings, connectionId: body.querySelector(".connection").value, contextMessages: Number(body.querySelector(".context").value), interval: Number(body.querySelector(".interval").value), format: body.querySelector(".format").value, mascotSize: Number(body.querySelector(".size").value) });
    body.querySelectorAll("input,select").forEach((input) => input.addEventListener("input", () => {
      settingsDraft = read();
    }));
    button(".save-settings", () => {
      const next = read();
      settingsDraft = undefined;
      run("settings", { settings: next }, "Settings saved for this chat.");
    });
    button(".reload-state", () => {
      settingsDraft = undefined;
      run("load", {}, "Reloaded.");
    });
  }
  panel.setVisible(false);
  mascot.setVisible(false);
  resize();
  changeChat(stateAPI.get("chat.active"));
  ctx.ready();
  return () => {
    if (destroyed)
      return;
    rpc("cancel").catch(() => {});
    destroyed = true;
    for (const item of pending.values()) {
      clearTimeout(item.timer);
      item.reject(new Error("KazzWare unloaded."));
    }
    pending.clear();
    for (const dispose of disposers.reverse())
      dispose();
    frame?.destroy();
    mascot.destroy();
    panel.destroy();
  };
}
export {
  setup
};
